<?php
declare(strict_types=1);
/** Shared email design. Callers supply trusted/escaped body HTML, never raw form HTML. */
function email_design(string $title,string $body,array $options=[]): string {
    $name=trim((string)($options['name']??''));$greeting=$name!==''?'Hello '.mb_substr($name,0,120).',':'Hello,';
    $site=(string)($options['site_url']??url('/'));$preheader=(string)($options['preheader']??$title);$logo=url('/assets/images/brand-lockup.png?v=20261027');
    $links='';foreach(social_links()as$label=>$href)$links.='<a href="'.e($href).'" style="color:#073b6a;display:inline-block;margin:4px 12px 4px 0;text-decoration:underline">'.e($label).'</a> ';
    $unsubscribe=$options['unsubscribe']??null;$preferences=$options['preferences']??null;
    $footer=$options['footer']??'<p>This is a service email about your request. It does not subscribe you to newsletter editions.</p><p>For newsletter emails, <a href="'.e(url('/newsletter/preferences/request')).'">manage your subscription or unsubscribe</a>.</p>';
    if($unsubscribe!==null)$footer='<p>You receive these emails because you confirmed your subscription to My Thoughts.</p><p><a href="'.e($unsubscribe).'">Unsubscribe</a>'.($preferences?' · <a href="'.e($preferences).'">Email preferences</a>':'').'</p>';
    $postal=trim((string)($options['postal_address']??app_config('mail.postal_address','')));$reference=trim((string)($options['reference']??''));
    $referenceHtml=$reference!==''?'<p style="font-size:12px;color:#536d7b">Reference: '.e(mb_substr($reference,0,120)).'</p>':'';
    // Preserve the established marker: durable outbox items must not be double-wrapped.
    return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.e($title).'</title></head><body data-email-design="waithaka-v1" data-brand-version="20261027" style="margin:0;padding:0;background:#edf4f8;color:#203c4f;font-family:Arial,Helvetica,sans-serif;line-height:1.7"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all">'.e($preheader).'</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#edf4f8"><tr><td align="center" style="padding:28px 12px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:600px;background:#ffffff;border:1px solid #d7e4eb;border-radius:16px;overflow:hidden"><tr><td style="padding:28px;border-top:6px solid #073b6a;border-bottom:4px solid #2f6f3e;background:#ffffff"><a href="'.e($site).'" style="display:inline-block;color:#073b6a;text-decoration:none"><img src="'.e($logo).'" alt="Waithaka Ndegwa" width="288" height="64" style="display:block;width:288px;max-width:100%;height:auto;border:0"></a><p style="color:#073b6a;font-size:17px;font-weight:bold;margin:15px 0 0">Waithaka Ndegwa</p><p style="color:#2f6f3e;margin:3px 0 0;font-size:14px">People · Ideas · Impact</p></td></tr><tr><td style="padding:30px 28px;font-size:16px"><p style="margin:0 0 20px">'.e($greeting).'</p><h1 style="font-family:Georgia,serif;font-size:29px;line-height:1.3;font-weight:normal;color:#073b6a;margin:0 0 20px">'.e($title).'</h1>'.$body.$referenceHtml.'</td></tr><tr><td style="padding:25px 28px;background:#f4f9fb;border-top:1px solid #d7e4eb"><p style="font-family:Georgia,serif;font-size:23px;color:#073b6a;margin:0 0 4px">Waithaka Ndegwa</p><p style="font-size:13px;color:#2f6f3e;margin:0 0 12px">People · Ideas · Impact</p><p style="font-size:13px;margin:0 0 12px"><a href="'.e(url('/')).'" style="color:#073b6a">www.waithakandegwa.com</a> · @iwaithakaw</p><p style="font-size:13px;line-height:2;margin:0 0 18px">'.$links.'</p><div style="font-size:12px;color:#536d7b">'.$footer.'<p><a href="'.e(url('/contact')).'">Contact</a> · <a href="'.e(url('/privacy')).'">Privacy</a> · <a href="'.e($site).'">Visit website</a></p>'.($postal!==''?'<p>'.nl2br(e($postal)).'</p>':'').'</div></td></tr></table><p style="font-size:12px;color:#536d7b">Practical ideas. Honest learning. Lasting value.</p></td></tr></table></body></html>';
}
function email_design_button(string $label,string $href): string {
    return '<p style="margin:26px 0"><a href="'.e($href).'" style="display:inline-block;background:#073b6a;color:#fff;border:12px solid #073b6a;border-left-width:22px;border-right-width:22px;border-radius:7px;text-decoration:none;font-weight:bold">'.e($label).'</a></p>';
}
function email_design_text(string $html): string {
    $html=preg_replace('~<div style="display:none[^>]*>.*?</div>~s','',$html)??$html;
    $html=preg_replace_callback('~<a\b[^>]*href="([^"]+)"[^>]*>(.*?)</a>~is',static fn($m)=>strip_tags($m[2]).' ('.html_entity_decode($m[1],ENT_QUOTES|ENT_HTML5,'UTF-8').')',$html)??$html;
    return trim(html_entity_decode(strip_tags(str_replace(['</p>','</h1>','</h2>','</tr>','<br>','<br />'],"\n",$html)),ENT_QUOTES|ENT_HTML5,'UTF-8'));
}
